const form=document.querySelector('#quoteForm');if(form){const block=document.querySelector('#quoteBlock');const chosen=new URLSearchParams(location.search).get('manzana');if(chosen&&/^[a-k]$/i.test(chosen))block.value=chosen.toUpperCase();form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);const message=['Hola, quisiera información sobre La Morada.','', 'Nombre: '+d.get('name'),'Correo: '+d.get('email'),'Teléfono: '+(d.get('phone')||'No indicado'),'Interés: '+(d.get('block')?'Manzana '+d.get('block'):'Asesoría para elegir una manzana'),'Lote: '+(d.get('lot')||'Por definir'),'Consulta: '+(d.get('message')||'Quisiera conocer precios, disponibilidad y condiciones.')].join('\n');document.querySelector('#quoteSummary').textContent=message;document.querySelector('#sendQuote').href='mailto:biosferaaqpsac@gmail.com?subject='+encodeURIComponent('Solicitud de cotización · La Morada')+'&body='+encodeURIComponent(message);form.hidden=true;const result=document.querySelector('#quoteResult');result.hidden=false;result.focus();});document.querySelector('#editQuote').onclick=()=>{document.querySelector('#quoteResult').hidden=true;form.hidden=false;block.focus();};}if(/^(#[a-k]|#club|#parque|#arborizacion)$/.test(location.hash))location.replace('plano.html'+location.hash);